<?php require __DIR__.'/inc/header.php';$title='Comments Moderation';$pdo=db();if(is_post()){verify_csrf();$pdo->prepare('UPDATE comments SET status=? WHERE id=?')->execute([post('status'),(int)post('id')]);flash('success','Comment updated.');redirect('/admin/comments.php');}$rows=$pdo->query('SELECT c.*,p.title FROM comments c LEFT JOIN content_posts p ON p.id=c.post_id ORDER BY c.id DESC')->fetchAll();?><div class="bg-white border rounded-2xl overflow-hidden soft"><div class="p-5 font-black">Comments</div><div class="overflow-x-auto"><table class="w-full text-sm"><thead class="bg-slate-50"><tr><th class="p-3 text-left">Author</th><th class="p-3 text-left">Post</th><th class="p-3 text-left">Comment</th><th class="p-3">Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr class="border-t"><td class="p-3"><?=e($r['author_name']??'Guest')?></td><td class="p-3 font-bold"><?=e($r['title']??'—')?></td><td class="p-3 max-w-lg"><?=e($r['comment'])?></td><td class="p-3"><form method="post" class="flex gap-2"><?=csrf_input()?><input type="hidden" name="id" value="<?=$r['id']?>"><select name="status" class="rounded-lg border-slate-200"><option <?=$r['status']==='approved'?'selected':''?>>approved</option><option <?=$r['status']==='pending'?'selected':''?>>pending</option><option <?=$r['status']==='spam'?'selected':''?>>spam</option></select><button class="px-3 py-2 rounded-lg bg-slate-950 text-white text-xs">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div><?php require __DIR__.'/inc/footer.php'; ?>
